from collections import Counter
def transform(g):
    h,w=len(g),len(g[0])
    c=Counter(x for row in g for x in row)
    bg=c.most_common(1)[0][0]
    out=[row[:] for row in g]
    # collect diagonal lines of non-bg cells
    seen=set(); lines=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and (i,j) not in seen:
                col=g[i][j]
                # find direction if part of diagonal pair
                line=[(i,j)]
                for di,dj in ((1,1),(1,-1)):
                    seg=[]
                    a,b=i+di,j+dj
                    while 0<=a<h and 0<=b<w and g[a][b]==col:
                        seg.append((a,b)); a,b=a+di,b+dj
                    a,b=i-di,j-dj
                    back=[]
                    while 0<=a<h and 0<=b<w and g[a][b]==col:
                        back.append((a,b)); a,b=a-di,b-dj
                    if len(seg)+len(back)>=1 and (len(seg)+len(back))>=2:
                        line=sorted(back+[(i,j)]+seg)
                        break
                for p in line: seen.add(p)
                if len(line)>=2: lines.append(line)
    for line in lines:
        di=line[1][0]-line[0][0]; dj=line[1][1]-line[0][1]
        step=di//max(abs(di),1) or 1, dj//max(abs(dj),1) or 1
        di,dj=step
        for s,e in ((line[-1],1),(line[0],-1)):
            a,b=s[0]+di*e, s[1]+dj*e
            while 0<=a<h and 0<=b<w and g[a][b]==bg:
                out[a][b]=line and g[line[0][0]][line[0][1]]
                a,b=a+di*e,b+dj*e
    return out

